const pageSize = 100, workers = 6, inventoryWorkers = 12, inventoryNodeLimit = 4000, videoExt = /\.(mkv|mp4|avi|m2ts|ts|mov|webm)$/i, subtitleExt = /\.(ass|ssa|srt|sub|vtt)$/i
