async function inspectGroup(group) { const evidence = await treeEvidence(group); if (!evidence.ok) return { ...group, state: 'unavailable', reason: evidence.reason }; const issues = triageIssues(group, evidence); if (!issues.length) return { ...group, state: 'clear', reason: '文件结构、目录名和集号没有发现异常；未调用模型或外部候选。', evidence, diagnosis: null }; const native = await nativeCandidateFor(group); let diagnosis = null, candidates = await candidatesFor(group, evidence, diagnosis, native), resolved = resolveIdentity(candidates, diagnosis); if (group.historyIds?.length || !native || resolved.state !== 'confirmed') { diagnosis = await diagnoseBundle(group, evidence); candidates = await candidatesFor(group, evidence, diagnosis, native); resolved = resolveIdentity(candidates, diagnosis) } return { ...group, ...resolved, state: resolved.state === 'confirmed' ? 'confirmed' : resolved.state, reason: `${issues.join('；')}。${diagnosisText(diagnosis)} ${resolved.reason}`, evidence, diagnosis } }
function organizationIssues(card) { if (!card?.evidence) return ['当前文件不可读，只能标记为历史残留或读取失败']; const issues = organizationAudit({ evidence: card.evidence, identity: card.identity, diagnosis: card.diagnosis }); if (!card.identity) return issues; const names = candidateNames(card.identity).map(norm).filter(Boolean), folderHasTitle = card.evidence.folderHints?.some(hint => { const value = norm(hint); return value && names.some(name => name === value || name.includes(value) || value.includes(name)) }); if (card.evidence.folderHints?.length && !folderHasTitle) issues.push('现有目录层级没有出现已确认作品名，需查看官方预览'); return issues }
function addStat(card) { if (card.state === 'clear') { run.value.stats.clear += 1; scope.value.fastClear += 1 } else if (card.state === 'confirmed') run.value.stats.confirmed += 1; else if (card.state === 'needs_selection') run.value.stats.selection += 1; else if (card.state === 'insufficient') run.value.stats.insufficient += 1; else if (card.state === 'non_media') run.value.stats.nonMedia += 1; else run.value.stats.unavailable += 1 }
async function waitIfPaused() { while (control.value.paused && !control.value.stopped) await new Promise(resolve => { resumeWaiter = resolve }); return !control.value.stopped }
function pause() { control.value.paused = true; run.value.phase = '已暂停：不再派发新包' }
function resume() { control.value.paused = false; run.value.phase = '继续检查'; resumeWaiter?.(); resumeWaiter = null }
function stop() { control.value.stopped = true; control.value.paused = false; run.value.phase = '正在停止：已发出的读取请求会结束'; resumeWaiter?.(); resumeWaiter = null }
async function inspect() { if (!canUseApi.value || loading.value) { notice.value = '当前 MoviePilot 没有注入认证 API，无法安全检查。'; return } loading.value = true; cards.value = []; selected.value = null; preview.value = null; scope.value = emptyScope(); control.value = { paused: false, stopped: false }; run.value = { ...emptyRun(), phase: '正在读取当前媒体库存', startedAt: Date.now() }; clock = window.setInterval(() => { run.value = { ...run.value } }, 1000); try { const [failed, successful, _sources, roots] = await Promise.all([historyRows(false, '失败整理历史'), historyRows(true, '成功整理历史'), readSources(), readDirectories()]); scope.value.failure = failed.length; scope.value.success = successful.length; const [inventory, failureGroups] = await Promise.all([inventoryGroups(roots), Promise.resolve(groupsFor(failed))]); const successKeys = new Set(successful.map(packageKey)), merged = mergeExactHistory(inventory, failureGroups), groups = merged.groups; if (merged.broad) scope.value.unavailable.push(`${merged.broad} 个失败历史指向宽泛父目录，只保留为线索，不再错误当作一个作品包扫描。`); scope.value.inventoryPackages = inventory.length; scope.value.recovered = [...failureGroups.values()].filter(group => successKeys.has(group.key)).length; scope.value.currentFailures = [...failureGroups.values()].filter(group => !successKeys.has(group.key)).length; scope.value.inventoryState = roots.length ? `已从 ${roots.length} 个已配置媒体库/下载根目录建立当前库存；先做快速结构筛查，只深查可疑包。` : '没有可读的配置媒体库或下载目录；未把历史伪装成库存。'; run.value.total = groups.length; run.value.phase = `范围已建立：当前库存 ${inventory.length} 包；开始快速筛查，仅对可疑包调用识别`; const queue = [...groups], worker = async () => { while (queue.length && await waitIfPaused()) { const group = queue.shift(); if (!group) return; run.value.current = `正在筛查第 ${run.value.completed + 1}/${run.value.total} 个当前包`; let card; try { card = await inspectGroup(group) } catch { card = { ...group, state: 'unavailable', reason: '读取这个包时出现异常；没有进行任何文件操作。' } } if (card.state !== 'clear') cards.value = [...cards.value, card]; run.value.completed += 1; addStat(card) } }; await Promise.all(Array.from({ length: Math.min(workers, groups.length) }, worker)); scope.value.verificationQueue = cards.value.length; run.value.finishedAt = Date.now(); if (control.value.stopped) notice.value = `已停止：完成 ${run.value.completed}/${run.value.total} 个包。已完成部分保留；全程零写入。`; else { run.value.phase = '检查完成'; notice.value = `已完成 ${run.value.completed} 个包：${scope.value.fastClear} 包快速通过，${cards.value.length} 包需要你查看；全程零写入。` } } catch (error) { run.value.phase = '检查未完成'; notice.value = error?.message || '无法建立当前媒体库存；没有改动文件。' } finally { loading.value = false; if (clock) window.clearInterval(clock); clock = null } }
function open(card, next = 'identity') { selected.value = card; preview.value = null; tab.value = next }
function choose(candidate) { selected.value = { ...selected.value, state: 'confirmed', identity: candidate, userConfirmed: true, reason: '已由你确认作品；下一步只能生成官方零写入预览。' }; cards.value = cards.value.map(card => card.key === selected.value.key ? selected.value : card) }
function previewPayload(item, target = {}) { return { fileitem: item.source, logid: item.historyIds?.[0], transfer_type: target.transfer_type || 'link', target_storage: target.target_storage, target_path: target.target_path, scrape: target.scrape, library_type_folder: target.library_type_folder, library_category_folder: target.library_category_folder, preview: true, reorganize: false, media_source: item.identity.media_source, media_id: item.identity.media_id, type_name: item.identity.type_name, season: item.identity.season } }
function previewIssues(result, target) { const items = result?.items || [], summary = result?.summary || {}, issues = []; if (!target?.target_path || !target?.transfer_type) issues.push('当前目录规则没有给出唯一完整目标'); if (!items.length && !summary.total) issues.push('官方没有返回逐文件预览'); if (summary.failed || items.some(item => item?.success === false || !item?.target)) issues.push('官方预览存在失败或缺失目标'); const episodes = items.map(item => Number(item?.episode)).filter(Number.isFinite); if (new Set(episodes).size !== episodes.length) issues.push('官方预览包含重复集号'); return issues }
async function auditOrganization() { if (!selected.value?.identity || selected.value.state !== 'confirmed') return; loading.value = true; preview.value = null; try { const base = previewPayload(selected.value), [historyRaw, targetRaw] = await Promise.all([props.api.post('transfer/manual/history', base, { feedback: 'silent' }), props.api.post('transfer/manual/target-path', base, { feedback: 'silent' })]), history = dataOf(historyRaw), target = dataOf(targetRaw); if (history?.success === false || target?.success === false) throw new Error(history?.message || target?.message || '官方整理审计被拒绝'); const historyData = history?.data ?? history, targetData = target?.data ?? target, raw = dataOf(await props.api.post('transfer/manual', previewPayload(selected.value, targetData), { feedback: 'silent' })); if (raw?.success === false) throw new Error(raw.message || '官方预览被拒绝'); const data = raw?.data ?? raw; preview.value = { history: historyData || {}, target: targetData || {}, data: data || {}, issues: previewIssues(data, targetData), fingerprint: selected.value.evidence?.fingerprint }; notice.value = preview.value.issues.length ? '已生成官方逐文件预览，但发现冲突，不能进入写入。' : '官方逐文件预览完成。旧硬链接清理仍锁定：官方预览没有逐项删除清单。' } catch (error) { notice.value = error?.message || '官方预览失败；没有改动文件。' } finally { loading.value = false } }
</script>

<template>
  <main class="governor-page">
    <header class="hero"><div><p class="eyebrow">MediaGovernor 1.7</p><h1>媒体治理工作台</h1><p>先快速筛出真正可疑的当前文件包；只有可疑包才调用原生识别、模型和候选复核。绝不静默删除旧硬链接。</p></div><div class="actions"><label class="limit">本次最多检查<select v-model.number="scopeLimit" :disabled="loading"><option :value="60">60 个包</option><option :value="180">180 个包</option><option :value="360">360 个包</option></select></label><button class="primary" :disabled="loading" @click="inspect">{{ loading ? '检查进行中…' : hasRun ? '重新检查' : '开始检查' }}</button><button v-if="loading && !control.paused" class="secondary" @click="pause">暂停</button><button v-if="loading && control.paused" class="secondary" @click="resume">继续</button><button v-if="loading" class="danger" @click="stop">停止</button></div></header>
    <section class="progress" aria-live="polite"><div class="progress-head"><strong>{{ run.phase }}</strong><span>{{ run.completed }}/{{ run.total }} 个当前包 · {{ elapsed }}</span></div><div class="track"><i :style="{ width: `${progress}%` }" /></div><p v-if="run.current">{{ run.current }}。先做本地结构筛查；只有可疑包才进入识别与候选核验。</p><div class="stats"><span>快速通过 <b>{{ run.stats.clear }}</b></span><span>已确认 <b>{{ run.stats.confirmed }}</b></span><span>待确认 <b>{{ run.stats.selection }}</b></span><span>资料不足 <b>{{ run.stats.insufficient }}</b></span><span>不可读取 <b>{{ run.stats.unavailable }}</b></span></div></section>
    <section class="scope"><h2>这次到底查了什么</h2><div class="scope-grid"><span>当前库存包 <b>{{ scope.inventoryPackages }}</b></span><span>快速通过 <b>{{ scope.fastClear }}</b></span><span>需要查看 <b>{{ scope.verificationQueue }}</b></span><span>失败历史 <b>{{ scope.failure }}</b></span><span>成功历史 <b>{{ scope.success }}</b></span></div><p>先扫描当前媒体库和下载目录，再把整理历史仅作为交叉线索。失败历史不是问题总数，也不会替代实际文件。{{ scope.inventoryState }}</p><p v-if="scope.unavailable.length" class="reason">{{ scope.unavailable.join('；') }}</p></section>
    <p v-if="notice" class="notice" role="status">{{ notice }}</p><nav class="tabs"><button :class="{ active: tab === 'identity' }" @click="tab = 'identity'">1. 找对作品</button><button :class="{ active: tab === 'organize' }" @click="tab = 'organize'">2. 整理正确</button><button :class="{ active: tab === 'fixtures' }" @click="tab = 'fixtures'">3. 验收样例</button></nav>
    <section v-if="tab === 'identity'" class="panel"><div class="section-head"><div><h2>找对作品</h2><p>这里只显示有结构异常、对应当前失败历史或标题冲突的包。模型只作补充判断；候选必须经过影视类型、年份和集数硬核验。</p></div><span class="chip">可用影视源 {{ sources.filter(videoSource).length }}</span></div><details v-if="sources.length" class="source-status"><summary>查看数据源查询状态</summary><p v-for="source in sources" :key="source.id || source.label">{{ source.label }}：{{ source.state }}{{ source.hits ? `（返回 ${source.hits} 条）` : '' }}</p></details><p v-if="!cards.length" class="empty">{{ hasRun ? '没有发现需要人工查看的问题包。' : '尚未读取。开始后只显示真正需要处理的包。' }}</p><article v-for="card in cards" :key="card.key" class="card" :class="card.state"><div><span class="state">{{ card.state === 'confirmed' ? '已定位问题包' : card.state === 'needs_selection' ? '需要你确认' : card.state === 'insufficient' ? '资料不足' : card.state === 'non_media' ? '样片或测试残留' : '来源不可读取或历史残留' }}</span><h3>{{ card.identity?.title || (card.state === 'non_media' ? '不是待整理正片' : '还没有可靠作品身份') }}{{ card.identity?.year ? `（${card.identity.year}）` : '' }}</h3><p v-if="card.evidence">{{ evidenceText(card.evidence) }}；已读 {{ card.evidence.directories }} 个目录节点、{{ card.evidence.entries.length }} 项名称证据。</p><p>{{ card.reason }}</p></div><button class="secondary" @click="open(card)">查看完整依据与候选</button></article></section>
    <section v-else-if="tab === 'organize'" class="panel"><div class="section-head"><div><h2>整理正确</h2><p>逐包核对当前目录层级、实际集号、视频数量与已确认作品。只有通过身份确认的包才能继续请求官方逐文件预览；旧硬链接删除仍锁定。</p></div><span class="chip">只读对账</span></div><p v-if="!organizationCards.length" class="empty">尚未读到任何当前视频包。</p><article v-for="card in organizationCards" :key="card.key" class="card" :class="{ confirmed: card.identity, needs_selection: !card.identity }"><div><span class="state">{{ card.identity ? '正在核对当前整理结构' : '身份未确认，整理核验锁定' }}</span><h3>{{ card.identity?.title || '尚无可靠作品身份' }}{{ card.identity?.year ? `（${card.identity.year}）` : '' }}</h3><p v-if="card.evidence">{{ evidenceText(card.evidence) }}。{{ organizationIssues(card).length ? organizationIssues(card).join('；') : '目录与集数没有发现可由当前只读证据证明的冲突。' }}</p><p v-else>{{ card.reason }}</p></div><button v-if="card.state === 'confirmed'" class="primary" @click="open(card, 'organize'); auditOrganization()">生成官方逐文件预览</button><button v-else class="secondary" @click="open(card, 'identity')">先核对作品身份</button></article></section>
    <section v-else class="panel"><div class="section-head"><div><h2>验收样例</h2><p>这些是脱敏固定样例。它们调用与实际检查相同的分包、候选确认和整理审计规则，不读取 NAS，也不调用模型。</p></div><span class="chip">{{ fixtures.filter(item => item.pass).length }}/{{ fixtures.length }} 通过</span></div><article v-for="fixture in fixtures" :key="fixture.id" class="card" :class="fixture.pass ? 'confirmed' : 'insufficient'"><div><span class="state">{{ fixture.pass ? '通过' : '失败' }}</span><h3>{{ fixture.label }}</h3><p>正确答案：{{ fixture.expected }}；实际结果：{{ fixture.actual }}</p></div><p>{{ fixture.pass ? '规则结果与预期一致。' : '规则结果与预期不一致；本版本不能进入候选安装。' }}</p></article></section>
    <div v-if="selected" class="backdrop" @click.self="selected = null"><section class="modal"><button class="close" aria-label="关闭" @click="selected = null">×</button><template v-if="tab === 'identity'"><p class="eyebrow">完整证据账本</p><h2>{{ selected.identity?.title || '候选核验' }}</h2><p v-if="selected.evidence">{{ evidenceText(selected.evidence) }}。已读取 {{ selected.evidence.entries.length }} 个目录项，证据指纹 {{ selected.evidence.fingerprint }}。</p><p>{{ selected.reason }}</p><section v-if="selected.diagnosis" class="diagnosis"><strong>整包模型判断</strong><p>{{ diagnosisText(selected.diagnosis) }}</p><p v-if="selected.diagnosis.reasons?.length">理由：{{ selected.diagnosis.reasons.join('；') }}</p><p v-if="selected.diagnosis.expected_episodes?.length">模型预期集号：{{ selected.diagnosis.expected_episodes.join('、') }}</p><p v-if="selected.diagnosis.evidence_indexes?.length">支持它的目录项编号：{{ selected.diagnosis.evidence_indexes.map(index => index + 1).join('、') }}</p></section><details v-if="selected.evidence"><summary>查看名称线索（{{ selected.evidence.queries.length }} 条）</summary><p>{{ selected.evidence.queries.join('；') || '没有可用线索' }}</p></details><details v-if="selected.evidence"><summary>查看发送给模型的目录结构（{{ selected.evidence.entries.length }} 项）</summary><ul><li v-for="(entry, index) in selected.evidence.entries" :key="`${entry.name}-${index}`">{{ '　'.repeat(entry.depth || 0) }}{{ entry.type === 'dir' ? '📁' : '📄' }} {{ entry.name }}</li></ul></details><div v-if="selected.candidates?.length" class="candidate-list"><article v-for="candidate in selected.candidates" :key="candidateKey(candidate)" class="candidate" :class="{ conflicted: candidate.conflicts?.length }"><div><strong>{{ candidate.title }}{{ candidate.year ? `（${candidate.year}）` : '' }}</strong><p>{{ candidate.original_title ? `原名：${candidate.original_title}` : '原名：未返回' }}{{ candidate.en_title ? `；英文：${candidate.en_title}` : '' }}</p><p class="candidate-meta">{{ candidateMeta(candidate) }}</p><p>检索线索：{{ candidate.queries?.join('；') || '原生文件识别' }}。支持：{{ candidate.reasons?.join('；') || '只有官方搜索命中' }}</p><p v-if="candidate.conflicts?.length" class="reason">冲突：{{ candidate.conflicts.join('；') }}</p></div><button class="secondary" @click="choose(candidate)">确认是这部</button></article></div><p v-else class="empty">MoviePilot 没有返回候选；这不代表文件为空。</p></template><template v-else><p class="eyebrow">官方逐文件预览</p><h2>{{ selected.identity?.title }}</h2><button class="primary" :disabled="loading" @click="auditOrganization">{{ loading ? '正在生成…' : '重新生成预览' }}</button><section v-if="preview" class="audit"><div class="audit-grid"><span>命中旧成功记录 <b>{{ preview.history?.history_count || 0 }}</b></span><span>预览文件 <b>{{ preview.data?.summary?.total || preview.data?.items?.length || 0 }}</b></span><span>可创建 <b>{{ preview.data?.summary?.success || 0 }}</b></span><span>预览失败 <b>{{ preview.data?.summary?.failed || 0 }}</b></span></div><p v-if="preview.issues.length" class="reason">已锁定：{{ preview.issues.join('；') }}</p><p v-else class="safe">新硬链接预览完整，但仍不执行。当前 MoviePilot 不会在预览中给出旧硬链接的逐项删除清单，插件不能替它猜测或静默删除。</p><details><summary>查看官方逐文件计划（{{ preview.data?.items?.length || 0 }} 项）</summary><ul><li v-for="(item, index) in preview.data?.items || []" :key="index">{{ item?.title || selected.identity?.title }} · {{ item?.episode ? `第 ${item.episode} 集` : '影片/未标集' }} · {{ item?.target ? '目标已生成' : '没有目标' }}</li></ul></details></section></template></section></div>
  </main>
</template>

