 0 14px}.tabs button{background:transparent;color:rgba(255,255,255,.7)}.tabs button.active{background:rgba(var(--v-theme-primary,139,92,246),.22);color:#fff}.panel{padding:24px}.section-head h2,.modal h2{margin:0 0 8px}.chip{padding:7px 10px;border-radius:999px;background:rgba(255,255,255,.08);font-size:13px;white-space:nowrap}.empty{padding:34px 0;margin:0;color:rgba(255,255,255,.65)}.card{padding:20px 0;border-top:1px solid rgba(255,255,255,.12)}.card:first-of-type{border-top:0}.state{color:rgb(var(--v-theme-primary,139,92,246));font-size:13px;font-weight:800}.needs_selection .state{color:#fbbf24}.insufficient .state,.unavailable .state{color:#fb7185}.card h3{margin:6px 0;font-size:22px}.reason{margin-top:8px!important;color:#fbbf24!important}.backdrop{position:fixed;inset:0;z-index:20;display:grid;place-items:center;padding:20px;background:rgba(0,0,0,.66)}.modal{position:relative;width:min(100%,840px);max-height:calc(100vh - 40px);overflow:auto;padding:30px}.close{position:absolute;right:16px;top:10px;border:0;background:none;color:inherit;font-size:30px;cursor:pointer}.candidate-list{margin-top:20px}.candidate{display:flex;justify-content:space-between;gap:16px;align-items:start;padding:16px 0;border-top:1px solid rgba(255,255,255,.12)}.candidate p{margin-top:6px}.candidate-meta{font-size:13px;color:rgba(255,255,255,.58)!important}.conflicted strong{color:#fbbf24}.safe{margin-top:16px!important;color:#86efac!important}.audit{margin-top:22px;padding-top:18px;border-top:1px solid rgba(255,255,255,.12)}.audit-grid{flex-wrap:wrap}.audit-grid span{display:grid;gap:4px;min-width:120px;padding:12px;border-radius:10px;background:rgba(255,255,255,.06);color:rgba(255,255,255,.72);font-size:13px}.audit-grid b{font-size:21px;color:#fff}details{margin-top:14px;padding:12px;border-radius:10px;background:rgba(255,255,255,.05)}summary{cursor:pointer;font-weight:700}ul{padding-left:20px;line-height:1.7}@media(max-width:720px){.governor-page{padding:24px 16px}.hero,.card,.section-head,.candidate{flex-direction:column;align-items:stretch}.hero h1{font-size:30px}.actions{justify-content:flex-start}.chip{white-space:normal}.audit-grid span{min-width:calc(50% - 9px)}}
.diagnosis{margin-top:18px;padding:14px;border-radius:10px;border:1px solid rgba(var(--v-theme-primary,139,92,246),.4);background:rgba(var(--v-theme-primary,139,92,246),.1)}.diagnosis p{margin-top:7px!important}
</style>
